        const result = calculateDiscount(price, quantity);
        if (result === expected) {
            console.log(`PASS: ${desc}`);
        } else {
            console.log(`FAIL: ${desc} (expected: ${expected}, got: ${result})`);
        }
    }
}

runTests();
